Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;

typedef pair<int, int> pii;

const int N = 11;
const int INF = 1e9;
const int MAXV = 2 * N * N + 5;

struct edge {
    int to, c, f, rev;
    edge() {}
    edge(int to_, int c_, int f_, int rev_)
        : to(to_), c(c_), f(f_), rev(rev_) {}
};

vector<edge> g[MAXV];
int d[MAXV], ptr[MAXV], s, t, n;
queue<int> q;

void addEdge(int v, int u, int cap) {
    g[v].push_back(edge(u, cap, 0, 0));
    g[u].push_back(edge(v, 0, 0, 0));
    g[v].back().rev = (int)g[u].size() - 1;
    g[u].back().rev = (int)g[v].size() - 1;
}

bool buildLevNet() {
    for (int i = 0; i <= t; ++i) d[i] = INF;
    d[s] = 0;
    q.push(s);

    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (size_t i = 0; i < g[v].size(); ++i) {
            int to = g[v][i].to;
            int cf = g[v][i].c - g[v][i].f;
            if (d[to] == INF && cf > 0) {
                d[to] = d[v] + 1;
                q.push(to);
            }
        }
    }
    return d[t] != INF;
}

int dfs(int v, int curFlow) {
    if (v == t) return curFlow;

    for (int &i = ptr[v]; i < (int)g[v].size(); ++i) {
        int to = g[v][i].to;
        int cf = g[v][i].c - g[v][i].f;

        if (d[to] == d[v] + 1 && cf > 0) {
            int add = dfs(to, min(curFlow, cf));
            if (add) {
                g[v][i].f += add;
                g[to][g[v][i].rev].f -= add;
                return add;
            }
        }
    }
    return 0;
}

int dinica() {
    int flow = 0;
    while (buildLevNet()) {
        memset(ptr, 0, sizeof(ptr));
        int add;
        while ((add = dfs(s, INF)) != 0) flow += add;
    }
    return flow;
}

int dst[N][N][N][N], tbad;
char a[N][N], b[N][N];
pii bad;
queue<pii> go;

const int X[] = {-1, 1, 0, 0};
const int Y[] = {0, 0, -1, 1};

bool check(pii v) {
    return v.first >= 0 && v.first < n && v.second >= 0 && v.second < n &&
           a[v.first][v.second] != 'Y' && a[v.first][v.second] != 'Z';
}

void bfs(int xs, int ys) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dst[xs][ys][i][j] = INF;

    dst[xs][ys][xs][ys] = 0;
    go.push(make_pair(xs, ys));

    while (!go.empty()) {
        pii v = go.front(); go.pop();

        if (dst[xs][ys][v.first][v.second] == dst[bad.first][bad.second][v.first][v.second] &&
            (bad.first != xs || bad.second != ys))
            continue;

        for (int k = 0; k < 4; ++k) {
            int nx = v.first + X[k];
            int ny = v.second + Y[k];
            pii nv = make_pair(nx, ny);

            if (check(nv) && dst[xs][ys][nx][ny] == INF &&
                dst[xs][ys][v.first][v.second] + 1 <= dst[bad.first][bad.second][nx][ny]) {
                dst[xs][ys][nx][ny] = dst[xs][ys][v.first][v.second] + 1;
                go.push(nv);
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &tbad);

    int px = 0, py = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            scanf(" %c", &a[i][j]);
            if (a[i][j] == 'Z') px = i, py = j;
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            scanf(" %c", &b[i][j]);

    bad = make_pair(px, py);
    bfs(px, py);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dst[bad.first][bad.second][i][j] = min(dst[bad.first][bad.second][i][j], tbad);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (check(make_pair(i, j))) bfs(i, j);

    s = 0;
    t = 2 * n * n + 1;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (a[i][j] != '0') addEdge(s, i * n + j + 1, a[i][j] - '0');
            if (b[i][j] != '0') addEdge(i * n + j + 1 + n * n, t, b[i][j] - '0');
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            for (int i1 = 0; i1 < n; ++i1)
                for (int j1 = 0; j1 < n; ++j1)
                    if (check(make_pair(i, j)) && check(make_pair(i1, j1)) &&
                        dst[i][j][i1][j1] <= dst[px][py][i1][j1])
                        addEdge(i * n + j + 1, i1 * n + j1 + 1 + n * n, INF);

    printf("%d", dinica());
    return 0;
}
